const al = document.createElement("puredashboard-alert");
al.type = "error"; al.title = "Save failed"; al.message = "Check your connection.";
al.closable = true;
al.addEventListener("close", (e) => { if (!confirm("Dismiss?")) e.preventDefault(); });
document.body.append(al);

const av = document.createElement("puredashboard-avatar");
av.name = "Ada Lovelace"; av.src = "/u/ada.png"; av.size = "lg";
document.body.append(av);   // shows the photo, or "AL" on a stable colour if it 404s

// <puredashboard-badge count="5"><button>Inbox</button></puredashboard-badge>
const b = document.querySelector("puredashboard-badge");
b.count = 12;            // "12"
b.max = 9;               // "9+"
b.dot = true;            // a dot, no number

const bc = document.createElement("puredashboard-breadcrumb");
bc.items = [
  { label: "Home", href: "#/" },
  { label: "Nodes", href: "#/nodes" },
  { label: "web-01" },            // last crumb = current page (plain text)
];
document.body.append(bc);

// <puredashboard-button variant="primary">Save</puredashboard-button>
// <puredashboard-button href="/docs">Docs</puredashboard-button>       ← renders an <a href>
// <puredashboard-button type="submit">Submit</puredashboard-button>    ← submits its <form>
const btn = document.createElement("puredashboard-button");
btn.variant = "primary"; btn.append("Save");
btn.addEventListener("click", () => save());

// <puredashboard-card title="Revenue">
//   <button data-card-extra>Export</button>
//   <p>Body content…</p>
//   <div data-card-footer>Updated just now</div>
// </puredashboard-card>
const card = document.createElement("puredashboard-card");
card.title = "Revenue";
card.append(someBodyNode);
container.append(card);

const cb = document.createElement("puredashboard-checkbox");
cb.label = "I agree to the terms"; cb.required = true;
cb.setAttribute("name", "agree");
cb.addEventListener("change", (e) => console.log(e.target.checked));
form.append(cb);

// <puredashboard-row gutter="md" align="middle" justify="between">
//   <puredashboard-col span="12">left</puredashboard-col>
//   <puredashboard-col span="12">right</puredashboard-col>
// </puredashboard-row>

const c = document.createElement("puredashboard-collapse");
c.items = [
  { key: "a", header: "Billing", content: "Manage your plan and invoices." },
  { key: "b", header: "Security", content: "Two-factor and sessions." },
];
c.multiple = false;                 // accordion (default)
c.value = "a";                      // open "Billing"
c.addEventListener("change", (e) => console.log(e.detail.value));
container.append(c);

const col = document.createElement("puredashboard-color");
col.value = "#4f9cf9"; col.showValue = true;
col.setAttribute("name", "brand");
col.addEventListener("change", (e) => console.log(e.target.value));
form.append(col);

const cb = document.createElement("puredashboard-combobox");
cb.options = [{ value: "us", label: "United States" }, { value: "vn", label: "Vietnam" }];
cb.placeholder = "Search a country"; cb.required = true;
cb.setAttribute("name", "country");
cb.addEventListener("change", (e) => console.log(e.detail.value));
form.append(cb);

// <puredashboard-layout>
//   <puredashboard-header>…</puredashboard-header>
//   <puredashboard-layout>            <!-- nested: row, has a sider -->
//     <puredashboard-sider collapsible>…</puredashboard-sider>
//     <puredashboard-content>…</puredashboard-content>
//   </puredashboard-layout>
//   <puredashboard-footer>…</puredashboard-footer>
// </puredashboard-layout>

const d = document.createElement("puredashboard-date");
d.min = "2020-01-01"; d.max = "2030-12-31"; d.required = true;
d.setAttribute("name", "born");
d.addEventListener("change", (e) => console.log(e.target.value));
form.append(d);

const d = document.createElement("puredashboard-descriptions");
d.title = "Server";
d.columns = 2;
d.bordered = true;
d.items = [
  { label: "Hostname", value: "web-01" },
  { label: "Region", value: "eu-west-1" },
  { label: "Notes", value: "Primary node", span: 2 },
];
panel.append(d);

// <puredashboard-empty description="No projects yet">
//   <button type="button">Create project</button>
// </puredashboard-empty>
const empty = document.createElement("puredashboard-empty");
empty.description = "No results";
container.append(empty);

// <puredashboard-flex justify="between" align="center" gap="md">
//   <button>One</button>
//   <button>Two</button>
// </puredashboard-flex>
const f = document.createElement("puredashboard-flex");
f.vertical = true; f.gap = "16px"; // 16px gap, column layout
f.append(a, b, c); // a, b, c become the direct flex items

// <puredashboard-layout>
//   <puredashboard-header>…</puredashboard-header>
//   <puredashboard-layout>            <!-- nested: row, has a sider -->
//     <puredashboard-sider collapsible>…</puredashboard-sider>
//     <puredashboard-content>…</puredashboard-content>
//   </puredashboard-layout>
//   <puredashboard-footer>…</puredashboard-footer>
// </puredashboard-layout>

// <puredashboard-form>
//   <puredashboard-input name="email" type="email" required></puredashboard-input>
//   <button type="submit">Save</button>
// </puredashboard-form>
const form = document.querySelector("puredashboard-form");
form.addEventListener("submit", (e) => console.log(e.detail.values)); // { email: "…" }

import "./gallery.js";
import { STORIES } from "./stories/index.js";
const g = document.createElement("puredashboard-gallery");
g.route = true; g.stories = STORIES;
document.body.append(g);

// <puredashboard-layout>
//   <puredashboard-header>…</puredashboard-header>
//   <puredashboard-layout>            <!-- nested: row, has a sider -->
//     <puredashboard-sider collapsible>…</puredashboard-sider>
//     <puredashboard-content>…</puredashboard-content>
//   </puredashboard-layout>
//   <puredashboard-footer>…</puredashboard-footer>
// </puredashboard-layout>

const inp = document.createElement("puredashboard-input");
inp.type = "email"; inp.required = true; inp.placeholder = "you@example.com";
inp.setAttribute("name", "email");
inp.addEventListener("change", (e) => console.log(e.detail.value));
form.append(inp);

const jv = document.createElement("puredashboard-json-view");
jv.data = { name: "web-01", up: true, ports: [80, 443], meta: null };
jv.theme = "auto";                       // follow the OS (default)
jv.theme = "dracula";                    // or pin a built-in palette
jv.level = 1;                            // start with only the root's fields expanded
jv.themes = { dark: { string: "#a5d6ff" } };   // tweak one colour in dark mode
document.body.append(jv);

// <puredashboard-layout>
//   <puredashboard-header>…</puredashboard-header>
//   <puredashboard-layout>            <!-- nested: row, has a sider -->
//     <puredashboard-sider collapsible>…</puredashboard-sider>
//     <puredashboard-content>…</puredashboard-content>
//   </puredashboard-layout>
//   <puredashboard-footer>…</puredashboard-footer>
// </puredashboard-layout>

const list = document.createElement("puredashboard-list");
list.header = "Recent nodes";
list.items = [
  { title: "web-01", description: "us-east-1", extra: "online" },
  { title: "web-02", description: "us-west-2", extra: "offline" },
];
list.bordered = true;
document.body.append(list);

// <puredashboard-markdown value="# Hello"></puredashboard-markdown>
const md = document.createElement("puredashboard-markdown");
md.value = "# Hello\n\nsome **markdown**";   // untrusted text is safe (textContent only)
container.append(md);

const nav = document.createElement("puredashboard-nav");
nav.items = [
  { label: "Dashboard", href: "#/", icon: "<svg …/>" },
  { label: "Nodes", children: [
    { label: "Web", href: "#/nodes/web", badge: "3" },
    { label: "DB",  href: "#/nodes/db" },
  ] },
];
nav.current = "#/nodes/web";
document.querySelector("aside").append(nav);

const num = document.createElement("puredashboard-number");
num.min = 0; num.max = 10; num.step = 2; num.value = "4";
num.setAttribute("name", "qty");
num.addEventListener("change", (e) => console.log(e.target.value));
form.append(num);

const p = document.createElement("puredashboard-pagination");
p.total = 200; p.pageSize = 10; p.page = 5;   // → pageCount 20
p.addEventListener("pagechange", (e) => load(e.detail.page));
document.body.append(p);

// <puredashboard-popconfirm title="Delete this row?" ok-danger>
//   <button>Delete</button>
// </puredashboard-popconfirm>
const pc = document.querySelector("puredashboard-popconfirm");
pc.addEventListener("confirm", () => actuallyDelete());
pc.addEventListener("cancel", () => {});

// <puredashboard-popover placement="bottom-start">
//   <button data-popover-trigger>Options</button>
//   <div data-popover-content>Hello</div>
// </puredashboard-popover>
const pop = document.querySelector("puredashboard-popover");
pop.addEventListener("open", () => console.log("opened"));
pop.show();

const pr = document.createElement("puredashboard-progress");
pr.value = 40; pr.max = 100;               // 40%
document.body.append(pr);
pr.variant = "circle"; pr.status = "success";   // green ring + check
pr.indeterminate = true;                        // animated sweep, no value

const rg = document.createElement("puredashboard-radio-group");
rg.options = [{ value: "s", label: "Small" }, { value: "m", label: "Medium" }];
rg.required = true;
rg.setAttribute("name", "size");
rg.setAttribute("aria-label", "Size");
rg.addEventListener("change", (e) => console.log(e.detail.value));
form.append(rg);

const r = document.createElement("puredashboard-rate");
r.count = 5; r.allowHalf = true; r.value = 3.5;
r.setAttribute("name", "rating");
r.addEventListener("change", (e) => console.log(e.detail.value));
form.append(r);

// <puredashboard-result status="success" title="Payment done" subtitle="Order #1234 confirmed.">
//   <button type="button">Go to dashboard</button>
// </puredashboard-result>
const res = document.createElement("puredashboard-result");
res.status = "404";
res.title = "Page not found";
res.subtitle = "The page you visited does not exist.";
container.append(res);

// <puredashboard-row gutter="md" align="middle" justify="between">
//   <puredashboard-col span="12">left</puredashboard-col>
//   <puredashboard-col span="12">right</puredashboard-col>
// </puredashboard-row>

const seg = document.createElement("puredashboard-segmented");
seg.options = [{ value: "list", label: "List" }, { value: "grid", label: "Grid" }];
seg.value = "grid";
seg.setAttribute("aria-label", "View");
seg.addEventListener("change", (e) => console.log(e.detail.value));
document.body.append(seg);

const sel = document.createElement("puredashboard-select");
sel.options = [{ value: "us", label: "United States" }, { value: "vn", label: "Vietnam" }];
sel.placeholder = "Choose a country"; sel.required = true;
sel.setAttribute("name", "country");
sel.addEventListener("change", (e) => console.log(e.target.value));
form.append(sel);

// <puredashboard-layout>
//   <puredashboard-header>…</puredashboard-header>
//   <puredashboard-layout>            <!-- nested: row, has a sider -->
//     <puredashboard-sider collapsible>…</puredashboard-sider>
//     <puredashboard-content>…</puredashboard-content>
//   </puredashboard-layout>
//   <puredashboard-footer>…</puredashboard-footer>
// </puredashboard-layout>

const sk = document.createElement("puredashboard-skeleton");
sk.variant = "text"; sk.lines = 4;                 // four shimmer bars
card.replaceChildren(sk);
// later, when data has loaded:
card.replaceChildren(realContent);

const sl = document.createElement("puredashboard-slider");
sl.min = 0; sl.max = 10; sl.step = 1; sl.value = "4"; sl.showValue = true;
sl.setAttribute("name", "volume");
sl.addEventListener("input", (e) => console.log(e.target.value));
form.append(sl);

// <puredashboard-space direction="horizontal" size="lg" align="center" justify="between">
//   <button>One</button>
//   <button>Two</button>
// </puredashboard-space>
const sp = document.createElement("puredashboard-space");
sp.direction = "vertical"; sp.size = 24; // 24px gap
sp.append(a, b, c); // a, b, c become the direct flex items

// <puredashboard-spinner label-visible label="Saving…"></puredashboard-spinner>
const sp = document.createElement("puredashboard-spinner");
sp.size = "lg"; sp.inline = true;
document.body.append(sp);

// <puredashboard-splitter style="height:240px">
//   <div data-size="60">left</div>
//   <div>right</div>
// </puredashboard-splitter>
const sp = document.querySelector("puredashboard-splitter");
sp.addEventListener("resize", (e) => console.log(e.detail.sizes)); // [60, 40]

const s = document.createElement("puredashboard-statistic");
s.title = "Revenue"; s.value = 1234567; s.prefix = "$"; s.precision = 2;
s.trend = "up";                       // → coloured ↑, green tint, sr-only "increase"
document.body.append(s);

const st = document.createElement("puredashboard-steps");
st.steps = [
  { label: "Account", description: "Your details" },
  { label: "Billing" },
  { label: "Done" },
];
st.current = 1;
st.clickable = true;
st.addEventListener("stepchange", (e) => { st.current = e.detail.index; });
document.body.append(st);

const sw = document.createElement("puredashboard-switch");
sw.label = "Enable notifications"; sw.checked = true;
sw.setAttribute("name", "notify");
sw.addEventListener("change", (e) => console.log(e.target.checked));
form.append(sw);

const t = document.createElement("puredashboard-table");
t.columns = [{ key: "name", label: "Name", sortable: true }];
t.rows = nodes; t.rowKey = (r) => r.name;
t.selectable = true; t.bulkActions = [{ name: "delete", label: "Delete", danger: true }];
t.addEventListener("bulkaction", (e) => removeRows(e.detail.rows));

const tabs = document.createElement("puredashboard-tabs");
tabs.tabs = [
  { id: "overview", label: "Overview", panelId: "panel-overview" },
  { id: "settings", label: "Settings", panelId: "panel-settings" },
];
tabs.addEventListener("tabchange", (e) => console.log(e.detail.value));
container.append(tabs); // panels #panel-overview / #panel-settings live in the page

// <puredashboard-tag color="success" closable round>Online</puredashboard-tag>
const tag = document.querySelector("puredashboard-tag");
tag.addEventListener("close", (e) => { if (isPinned) e.preventDefault(); });

const ta = document.createElement("puredashboard-textarea");
ta.rows = 5; ta.required = true; ta.placeholder = "Notes…"; ta.autoGrow = true;
ta.setAttribute("name", "notes");
ta.addEventListener("change", (e) => console.log(e.target.value));
form.append(ta);

const t = document.createElement("puredashboard-time");
t.min = "09:00"; t.max = "17:00"; t.step = 60; t.required = true;
t.setAttribute("name", "start");
t.addEventListener("change", (e) => console.log(e.target.value));
form.append(t);

const tl = document.createElement("puredashboard-timeline");
tl.items = [
  { label: "09:00", content: "Deploy started", color: "accent" },
  { label: "09:02", content: "Build passed",   color: "success" },
  { label: "09:05", content: "Rollout failed", color: "error" },
];
tl.pending = "Retrying…";
document.body.append(tl);

// <puredashboard-titlebar platform="windows" controls>
//   <span data-titlebar-center>My App</span>
// </puredashboard-titlebar>
const bar = document.querySelector("puredashboard-titlebar");
// Tauri v2:
import { getCurrentWindow } from "@tauri-apps/api/window";
const w = getCurrentWindow();
bar.addEventListener("minimize", () => w.minimize());
bar.addEventListener("maximizetoggle", async () => { await w.toggleMaximize(); bar.maximized = await w.isMaximized(); });
bar.addEventListener("close", () => w.close());

// <puredashboard-tooltip text="Delete" placement="bottom">
//   <button aria-label="Delete">🗑</button>
// </puredashboard-tooltip>
const tip = document.createElement("puredashboard-tooltip");
tip.text = "Save"; tip.append(button);

const tree = document.createElement("puredashboard-tree");
tree.nodes = [
  { id: "src", label: "src", children: [
    { id: "app", label: "app.js" },
    { id: "lib", label: "lib", children: [{ id: "util", label: "util.js" }] },
  ] },
  { id: "readme", label: "README.md" },
];
tree.expandedKeys = ["src"];
tree.selectedKey = "app";
tree.addEventListener("select", (e) => console.log(e.detail.key, e.detail.node));
document.body.append(tree);

const u = document.createElement("puredashboard-upload");
u.accept = "image/*"; u.multiple = true; u.maxSize = 5 * 1024 * 1024;
u.labels = { browse: "Kéo & thả ảnh, hoặc bấm để chọn" };
u.addEventListener("files", (e) => submitBtn.disabled = !e.detail.length);
submitBtn.onclick = () => u.upload("/api/upload");
